const current = $input.first()?.json ?? {};

let apiResult = {};

try {
  const raw = current.api_result_json;

  apiResult =
    typeof raw === 'string'
      ? JSON.parse(raw)
      : (raw ?? {});
} catch (error) {
  throw new Error(
    'No se pudo interpretar api_result_json del caso persistido.'
  );
}

const caseArtifact = apiResult.case_artifact;

if (
  !caseArtifact ||
  typeof caseArtifact !== 'object' ||
  Array.isArray(caseArtifact)
) {
  throw new Error(
    'El caso persistido no contiene un case_artifact válido.'
  );
}

return [
  {
    json: {
      ...current,
      case_artifact: caseArtifact,
    },
  },
];

