const e = $('Authorize and route').first().json;
const c = $input.first().json;

const owner = e.access?.role === 'OWNER';

const owned =
  String(c.telegram_user_id) === String(e.telegram_user_id) &&
  String(c.telegram_chat_id) === String(e.telegram_chat_id);

const canSee = owner || owned;
const isCallback = e.route === 'CALLBACK';

const approvalExpiry = c.approval_expires_at
  ? Date.parse(c.approval_expires_at)
  : NaN;

const expired =
  canSee &&
  c.approval_status === 'PENDING' &&
  Number.isFinite(approvalExpiry) &&
  approvalExpiry <= Date.now();

const act = e.args?.[0];
const callbackCaseId = e.args?.[1];
const callbackVersion = e.args?.[2];

const allowed =
  isCallback &&
  canSee &&
  e.private_chat &&
  ['OWNER', 'EVALUATOR'].includes(e.access?.role) &&
  String(c.caso_id) === String(callbackCaseId) &&
  c.estado === 'PENDIENTE_APROBACION' &&
  c.approval_status === 'PENDING' &&
  !expired &&
  String(c.version_caso) === String(callbackVersion) &&
  ['APR', 'REJ'].includes(act);

const folio =
  c?.caso_id ||
  String(e.args?.[isCallback ? 1 : 0] || '');

let reply;

if (isCallback) {
  reply = allowed
    ? ''
    : expired
      ? `El periodo de aprobación del caso ${folio} expiró.`
      : 'Decisión no autorizada o caso no vigente.';
} else {
  reply = canSee
    ? `Caso ${folio} | Fecha: ${c.fecha_corte} | Modo: ${c.execution_mode} | Estado: ${
        expired ? 'EXPIRADO' : c.estado
      } | Dictamen: ${c.dictamen_tecnico} | Aprobación: ${
        expired ? 'EXPIRED' : c.approval_status
      } | Actualización: ${c.updated_at}`
    : 'Folio no disponible.';
}

return [
  {
    json: {
      ...e,
      case_row: c,
      canSee,
      is_callback: isCallback,
      expired,
      allowed,
      new_state:
        act === 'APR'
          ? 'APROBADA_HUMANAMENTE'
          : 'RECHAZADA_HUMANAMENTE',
      reply,
    },
  },
];

