/estado FOLIO
/acceso CODIGO
/ayuda';return[{json:{...j,reply:(j.route==='/start'||j.route==='/ayuda')?h:(j.reply||'El servicio de cálculo no está disponible en este momento. El caso quedó detenido y no fue aprobado.'),reply_markup:j.reply_markup||null}}];

const api = $('Invoke YieldCurve API once').first().json;
const req = $('Validate new case request').first().json;
const p = $input.first().json;

const curve = api.resultado_curva || {};
const audit = api.auditoria || {};
const agents = api.agentes || api;

const elara = agents.elara || api.elara || {};
const siena = agents.siena || api.siena || {};
const nash = agents.nash || api.nash || {};
const atenea = agents.atenea || api.atenea || {};

const missing = elara.datos_faltantes;

// ---------------------------------------------------------
// CAPA DE PRESENTACIÓN
// No modifica códigos técnicos ni valores persistidos.
// ---------------------------------------------------------

const friendly = {
  PENDIENTE_APROBACION: 'Pendiente de aprobación',
  PENDIENTE_ACLARACION: 'Pendiente de aclaración',
  PENDIENTE_EJECUCION: 'Pendiente de ejecución',
  APROBADA_HUMANAMENTE: 'Aprobado por decisión humana',
  RECHAZADO: 'Rechazado',
  DETENIDO: 'Detenido',
  EXPIRADO: 'Expirado',

  ACEPTAR: 'Aceptado',
  RECHAZAR: 'Rechazado',

  DATOS_VALIDOS: 'Datos validados',
  CALCULO_COMPLETADO: 'Cálculo completado',
  DICTAMEN_TECNICO_VALIDADO: 'Dictamen técnico validado',
  VALIDADO: 'Validado',
  NO_VALIDADO: 'No validado',

  NOT_AVAILABLE: 'No disponible',
  NO_DISPONIBLE: 'No disponible',
};

const pretty = (value) => {
  if (value === null || value === undefined || value === '') {
    return 'N/D';
  }

  if (friendly[value]) {
    return friendly[value];
  }

  const text = String(value).replaceAll('_', ' ').toLowerCase();
  return text.charAt(0).toUpperCase() + text.slice(1);
};

const formatDate = (value) => {
  if (!value) return 'N/D';

  const parts = String(value).split('-');

  if (parts.length === 3) {
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  }

  return value;
};

const sourceMode = api.fuente_datos?.source_mode;

const sourceFriendly = {
  FIXTURE_BANXICO_2026_11_11: 'Banxico · Snapshot DEMO 11/11/2026',
  'FIXTURE_BANXICO_2026-11-11': 'Banxico · Snapshot DEMO 11/11/2026',
  BANXICO_SIE_LIVE: 'Banxico SIE · Datos en vivo',
  NOT_QUERIED: 'Fuente no consultada',
}[sourceMode] || pretty(sourceMode);

const methodology = curve.metodologia;

const methodologyFriendly = {
  EXCEL_BOOTSTRAP_182D_V1: 'Bootstrap 182 días · V1',
}[methodology] || pretty(methodology);

const formatError = (value) => {
  if (value === null || value === undefined || value === '') {
    return 'N/D';
  }

  const number = Number(value);

  if (!Number.isFinite(number)) {
    return String(value);
  }

  if (number === 0) {
    return '0';
  }

  if (Math.abs(number) < 0.0001) {
    const [coefficient, exponent] = number.toExponential(2).split('e');

    const superscriptMap = {
      '-': '⁻',
      '+': '',
      '0': '⁰',
      '1': '¹',
      '2': '²',
      '3': '³',
      '4': '⁴',
      '5': '⁵',
      '6': '⁶',
      '7': '⁷',
      '8': '⁸',
      '9': '⁹',
    };

    const exponentPretty = exponent
      .split('')
      .map((char) => superscriptMap[char] ?? char)
      .join('');

    return `${coefficient} × 10${exponentPretty}`;
  }

  return number.toLocaleString('es-MX', {
    maximumSignificantDigits: 6,
  });
};

// ---------------------------------------------------------
// ELEGIBILIDAD DE APROBACIÓN
// ---------------------------------------------------------

const eligible =
  api.estado === 'PENDIENTE_APROBACION' &&
  api.requiere_aprobacion_humana === true &&
  Boolean(api.resultado_curva) &&
  Array.isArray(curve.pillars) &&
  curve.pillars.length > 0 &&
  audit.tecnicamente_valida === true &&
  p.approval_status === 'PENDING';

// ---------------------------------------------------------
// MENSAJE TELEGRAM
// ---------------------------------------------------------

let reply =
  `Caso ${req.caso_id}\n` +
  `Fecha: ${formatDate(req.fecha_corte)} · Modo: ${req.execution_mode}\n\n` +

  `Estado: ${pretty(api.estado || 'NO_DISPONIBLE')}\n\n` +

  `Elara: ${pretty(elara.decision || elara.estado)}\n` +
  `Siena: ${pretty(siena.estado)}\n` +
  `Nash: ${pretty(nash.estado)}\n` +
  `Atenea: ${pretty(atenea.estado)}\n\n` +

  `Fuente: ${sourceFriendly}\n` +
  `Metodología: ${methodologyFriendly}\n` +
  `Instrumentos: ${curve.instrument_count ?? 'N/D'}\n` +
  `Error máx. de repricing: ${formatError(curve.max_absolute_repricing_error)}\n` +
  `Auditoría técnica: ${audit.tecnicamente_valida === true ? 'Válida' : 'No válida'}`;

if (
  api.estado === 'PENDIENTE_ACLARACION' &&
  Array.isArray(missing) &&
  missing.length
) {
  reply += `\n\nDatos faltantes: ${missing.map(pretty).join(', ')}`;
}

if (eligible) {
  reply += '\n\nEste resultado requiere aprobación humana.';
}

// ---------------------------------------------------------
// OUTPUT
// ---------------------------------------------------------

return [
  {
    json: {
      ...p,
      reply,
      eligible_for_approval: eligible,
      reply_markup: eligible
        ? {
            inline_keyboard: [
              [
                {
                  text: '✅ Aprobar',
                  callback_data: `APR|${req.caso_id}|${req.version_caso}`,
                },
                {
                  text: '❌ Rechazar',
                  callback_data: `REJ|${req.caso_id}|${req.version_caso}`,
                },
              ],
            ],
          }
        : null,
    },
  },
];
